        if yesterday_bids:
            max_prev = max(yesterday_bids)
            if max_prev > 140 * 0.8:
                target_bid = min(my_budget, 140 * 0.3)
            else:
                target_bid = min(my_budget, max_prev + 1.0)
        else:
            target_bid = min(my_budget, 140 * 0.5)

